void mutate_buffer(char *buf, int size)
{
    int i;

    for (i = 0; i < size; i++) {
        if ((rand() % 101) <= 13) {
            buf[i] = (char)((rand() % 255) + 1);
        }
    }
}

int add_10_random_bytes(char *buf, int size)
{
    int i;

    for (i = 0; i < 10; i++) {
        buf[size + i] = (char)((rand() % 255) + 1);
    }
    return size + 10;
}
